const D = { energy: .62, scale: 1, speed: 1, density: .55, haze: .6, twist: .55, hue: 24, x: .5, y: .3, style: 'sandstone', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A sandstone slot canyon, rendered volumetrically into a coarse buffer: telescoping
// wall fins recede toward a glowing crack of sky, aerial haze stacks up between them, and a
// shaft of light spears down through suspended dust. The camera dollies forward forever, so
// the strata slide past in parallax and fins are reborn at the vanishing point.
// The medium — light in dust — is the subject; the rock only shapes it. ----
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(72, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
}

const sd = P.seed | 0;
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> not >> : an arithmetic fold caps the hash at 0.5
}
function fr(i) { return hsh(i * 7 + 13, i * 31 + 5); }
function vn(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
  const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
  const a = hsh(ix, iy), b = hsh(ix + 1, iy), c = hsh(ix, iy + 1), d = hsh(ix + 1, iy + 1);
  return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
}
// hue 0..360, sat 0..1, val 0..1 -> rgb 0..1 (local: never call colorMode on a buffer)
function hsv(h, s, v) {
  h = ((h % 360) + 360) % 360;
  const c = v * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = v - c;
  const k = Math.floor(h / 60) % 6;
  let r, g2, b;
  if (k === 0) { r = c; g2 = x; b = 0; } else if (k === 1) { r = x; g2 = c; b = 0; }
  else if (k === 2) { r = 0; g2 = c; b = x; } else if (k === 3) { r = 0; g2 = x; b = c; }
  else if (k === 4) { r = x; g2 = 0; b = c; } else { r = c; g2 = 0; b = x; }
  return [r + m, g2 + m, b + m];
}

const tt = K.t;
const style = P.style;
const en = P.energy;
const NL = 7;
const aspect = width / height;

// ---- perpetual forward dolly: monotonic, never reverses, rate modulated on incommensurate
// rates so the walk never repeats. Guarded against t0 resets (K.t can jump backwards). ----
if (S.dz == null) S.dz = 0;
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
const dtF = Math.max(0, Math.min(0.1, K.t - S.lastT));
S.lastT = K.t;
S.dz += dtF * (0.16 + P.speed * 0.20) * (0.82 + 0.18 * Math.sin(tt * 0.083) + 0.09 * Math.sin(tt * 0.191 + 1.2) + K.swell * 0.08 + A.bass * 0.10);
const dz = S.dz;

// ---- per-fin geometry, precomputed once per frame (near -> far) ----
const fHalf = [], fId = [], fProg = [], fWobA = [], fWobF = [], fWobP = [], fWob2 = [], fSway = [], fRate = [];
for (let L = NL - 1; L >= 0; L--) {
  const raw = (L + dz) % NL;
  const prog = raw / NL;                         // 0 = far, ~1 = near
  const p2 = Math.pow(prog, 2.3);
  const id = ((Math.floor(L + dz) % 9973) + 9973) % 9973;
  // apparent half-gap in units of canvas WIDTH; the slot telescopes open toward the viewer
  fHalf.push((0.010 + p2 * 0.62) * P.scale / aspect * 1.35 * (0.72 + fr(id * 11 + 7) * 0.62));
  fProg.push(prog); fId.push(id);
  fWobA.push((0.06 + P.twist * 0.26) * (0.16 + p2 * 0.95) * P.scale / aspect);
  fWobF.push(2.1 + fr(id * 5 + 2) * 3.4);
  fWobP.push(fr(id * 5 + 3) * 6.28 + tt * 0.06 * (0.5 + fr(id) * 0.6));
  fWob2.push(fr(id * 5 + 6) * 6.28);
  fSway.push((fr(id * 3 + 1) - 0.5) * (0.03 + p2 * 0.10) * P.scale / aspect);
  fRate.push(0.30 + p2 * 1.5);                   // strata parallax rate: near fins slide faster
}
const NF = fHalf.length;

// ---- palette ----
const hb = ((P.hue + (K.section | 0) * 6) % 360 + 360) % 360;
function rockCol(d, lit) {
  if (style === 'ice')          return hsv(196 + d * 16, 0.34 - lit * 0.20, (0.30 + Math.sqrt(lit) * 0.66) * (1 - d * 0.30) + 0.14);
  if (style === 'chiaroscuro')  return hsv(hb + 8, 0.05 + lit * 0.03, (0.012 + lit * lit * 1.05) * (1 - d * 0.52) + 0.012);
  if (style === 'ink')          return hsv(hb + 20, 0.07 + lit * 0.05, (0.26 + lit * 0.46) * (1 - d * 0.24) + 0.26);
  if (style === 'blueprint')    return hsv(210 + d * 8, 0.62 - lit * 0.16, (0.10 + lit * 0.34) * (1 - d * 0.26) + 0.07);
  // sandstone: incandescent amber at the lip, violet-blue in the depths
  return hsv(hb - 10 + lit * 30 + d * 30, 0.72 - lit * 0.32 + d * 0.05, (0.06 + lit * 0.80) * (1 - d * 0.44) + 0.045);
}
const hazeC = style === 'ice' ? hsv(200, 0.16, 0.80) : style === 'chiaroscuro' ? hsv(hb + 10, 0.04, 0.50)
            : style === 'ink' ? hsv(hb + 15, 0.05, 0.88) : style === 'blueprint' ? hsv(208, 0.45, 0.42)
            : hsv(hb + 18, 0.36, 0.72);
const glowC = style === 'ice' ? hsv(192, 0.10, 1.0) : style === 'chiaroscuro' ? hsv(42, 0.05, 1.0)
            : style === 'ink' ? hsv(35, 0.04, 0.99) : style === 'blueprint' ? hsv(196, 0.22, 0.95) : hsv(hb + 12, 0.20, 1.0);

// ---- the shaft: sweeps on incommensurate rates (slow — never a strobe) ----
const shA = -0.30 + 0.22 * Math.sin(tt * 0.037) + 0.09 * Math.sin(tt * 0.091 + 1.4);
const shT = Math.tan(shA);
const shW = 0.10 * P.scale + 0.02;
const cxn = P.x, hzn = P.y;

const g = S.g; g.loadPixels(); const px = g.pixels;
const dustZ = tt * 0.5, dustX = tt * 0.11;
const hazeAmt = P.haze;

for (let j = 0; j < BH; j++) {
  const ny = j / BH;
  for (let i = 0; i < BW; i++) {
    const nx = i / BW - cxn;
    const ax = Math.abs(nx), sgn = nx < 0 ? -1 : 1;
    // ---- occlusion walk: nearest fin whose wall covers this pixel wins ----
    let hitD = 1, hitLit = 0, hitStr = 0, hit = -1;
    for (let f = 0; f < NF; f++) {
      const wob = Math.sin(ny * fWobF[f] + fWobP[f]) * fWobA[f]
                + Math.sin(ny * 6.7 + fWob2[f]) * fWobA[f] * 0.34;
      const edge = fHalf[f] + wob * sgn + fSway[f] * sgn;
      if (ax >= edge) {
        hit = f;
        hitD = 1 - fProg[f];
        // distance into the rock face from the lit lip
        const into = (ax - edge) / (0.05 + fProg[f] * 0.5);
        hitLit = Math.exp(-into * 1.5) * (0.30 + fProg[f] * 0.85);
        // strata: bands running along the wall, scrolling with the dolly (parallax)
        const w = ny * (9 + fProg[f] * 16) + dz * fRate[f] * 2.2 + fId[f] * 3.7;
        const wv = w + Math.sin(w * 0.31 + (ax - edge) * 9) * 1.5;
        let band = 0.5 + 0.5 * Math.sin(wv * 1.35 + Math.sin(wv * 0.37) * 2.1);
        band = Math.pow(band, 1.4);
        const coarse = 0.5 + 0.5 * Math.sin(wv * 0.29 + 1.3);
        const grit = vn((ax - edge) * 220 + fId[f] * 17, w * 5.5) - 0.5;
        hitStr = band * 0.52 + coarse * 0.30 + grit * 0.26;
        break;
      }
    }
    let r, g2, b;
    if (hit < 0) {
      // ---- looking straight up the slot: the sky crack ----
      const dsl = Math.abs(nx) / (0.05 * P.scale + 0.012) + Math.abs(ny - hzn) * 1.1;
      const k = Math.exp(-dsl * 0.55);
      const bright = (0.30 + en * 0.75) * (0.35 + k * 0.9);
      r = glowC[0] * bright; g2 = glowC[1] * bright; b = glowC[2] * bright;
    } else {
      const lit = hitLit * (0.5 + en * 0.85);
      const c = rockCol(hitD, Math.max(0, Math.min(1, lit)));
      const sh2 = 0.55 + hitStr * 0.85;           // strata modulate the rock brightness
      r = c[0] * sh2; g2 = c[1] * sh2; b = c[2] * sh2;
      // aerial haze: the deeper the fin, the more atmosphere is stacked in front of it
      const ha = Math.min(0.88, hitD * hitD * 0.95 * hazeAmt);
      r += (hazeC[0] * 0.62 - r) * ha; g2 += (hazeC[1] * 0.62 - g2) * ha; b += (hazeC[2] * 0.62 - b) * ha;
