    // ---- volumetric shaft: additive light integrated through dusty air, in FRONT of the rock ----
    const sxm = cxn + (ny - hzn) * shT;
    const dsh = Math.abs(nx - (sxm - cxn)) / shW;
    if (dsh < 2.2 && ny > hzn - 0.12) {
      // dust density gives the beam volumetric texture and keeps it drifting
      const dn = 0.55 + 0.45 * vn(nx * 26 + dustX * 6, ny * 20 - dustZ);
      const fall = Math.exp(-dsh * dsh * 1.05) * Math.min(1, (ny - hzn + 0.12) * 2.4);
      const bm = fall * dn * (0.30 + en * 0.62) * (0.80 + K.swell * 0.14 + A.mid * 0.26) * (0.35 + hazeAmt * 0.9);
      r += glowC[0] * bm; g2 += glowC[1] * bm; b += glowC[2] * bm;
