    // ---- ambient dust glow near the slot, so the air itself reads as a medium ----
    const amb = Math.exp(-Math.abs(nx) * 3.4) * Math.exp(-Math.abs(ny - hzn) * 1.5) * (0.10 + en * 0.20) * (0.4 + hazeAmt * 0.8);
    r += glowC[0] * amb; g2 += glowC[1] * amb; b += glowC[2] * amb;

    const o = 4 * (j * BW + i);
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, g2 * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
