g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- suspended motes, drawn crisp over the upscaled buffer ----
const NM = Math.round(24 + P.density * 120);
const uu = Math.min(width, height);
push();
blendMode(ADD);
noStroke();
for (let i = 0; i < NM; i++) {
  const f1 = fr(i * 2 + 1), f2 = fr(i * 2 + 2), f3 = fr(i * 3 + 5);
  const my = ((f2 + tt * (0.006 + f3 * 0.024) * (0.3 + P.speed * 0.8)) % 1.12) - 0.06;
  const mx = f1 + Math.sin(tt * (0.21 + f3 * 0.5) + f1 * 6.28) * 0.02
                + Math.sin(tt * (0.07 + f2 * 0.16) + f2 * 6.28) * 0.035;
  const sxm = cxn + (my - hzn) * shT;
  const inSh = Math.max(0, 1 - Math.abs(mx - sxm) / (shW * 1.5));
  const br = (0.06 + inSh * inSh * 1.0) * (0.5 + en * 0.7);
  const sz = (0.8 + f3 * 2.2) * (uu / 640) * (0.6 + inSh * 1.3);
  fill(0, 0, 100, 42 * br * (0.7 + 0.3 * Math.sin(tt * (1.1 + f1 * 2.3) + i)) * (P.alpha / 100));
  ellipse(mx * width, my * height, sz, sz);
}
blendMode(BLEND);
pop();
drawingContext.shadowBlur = 0;
